  INSERT INTO source_capture_ledger (publisher, field_type, items, job) VALUES
    ('oad', 'award', 23, 'cleanup:fix-a2-a3-d-2026-11-03 | open items 1-3: 22 rows moved or given the list URL, 1 new row 2026 No. 773 on Tempura Yamanoue Ginza | Ben Nov 3 20:42 ET "1A, 2A, 3A, 4A, 5A, 6A"'),
