    ('oad', 'city_label', 22, 'cleanup:fix-a2-a3-d-2026-11-03 | open items 1-2: city labels of the 11 new venues; Yama no Ue city from the owner site | Ben Nov 3 20:42 ET "1A, 2A, 3A, 4A, 5A, 6A"');
  -- POST gates
  IF (SELECT count(*) FROM venues) <> 11336 OR (SELECT count(*) FROM venues WHERE status='active') <> 11042 OR (SELECT count(*) FROM venues WHERE status='closed') <> 294 THEN RAISE EXCEPTION 'venues after'; END IF;
  IF (SELECT count(*) FROM awards) <> 25324 OR (SELECT count(*) FROM awards WHERE source_id='michelin' AND year=2025 AND source_url IS NULL) <> 3028 OR (SELECT count(*) FROM awards WHERE source_id='michelin' AND year=2026 AND source_url IS NULL) <> 434 THEN RAISE EXCEPTION 'awards after'; END IF;
  IF (SELECT count(*) FROM slugs) <> 13184 OR (SELECT count(*) FROM slugs WHERE NOT is_canonical) <> 1848 OR (SELECT count(*) FROM slugs WHERE is_canonical) <> 11336 OR (SELECT count(*) FROM listings) <> 11336 OR (SELECT count(*) FROM city_label_source) <> 24079 THEN RAISE EXCEPTION 'child tables after'; END IF;
  SELECT count(*) INTO x FROM venues v WHERE (SELECT count(*) FROM slugs s WHERE s.venue_id=v.id AND s.property_id='eats' AND s.is_canonical) <> 1; IF x <> 0 THEN RAISE EXCEPTION 'canonical %', x; END IF;
  IF (SELECT count(*) FROM cities) <> 3281 OR (SELECT sum(venues_count) FROM cities) <> 11042 OR (SELECT count(*) FROM redirects) <> 13 OR (SELECT count(*) FROM price) <> 7759 THEN RAISE EXCEPTION 'cities, redirects, price after'; END IF;
  IF (SELECT count(*) FROM cities c LEFT JOIN city_venue_counts k ON k.city_id=c.id WHERE c.venues_count IS DISTINCT FROM coalesce(k.active_venues,0)) <> 0 THEN RAISE EXCEPTION 'city view after'; END IF;
  IF (SELECT count(*) FROM listings l JOIN venues v ON v.id=l.venue_id WHERE v.status='closed' AND l.published) <> 0 OR (SELECT count(*) FROM listings l JOIN venues v ON v.id=l.venue_id WHERE v.status='active' AND NOT l.published) <> 0 THEN RAISE EXCEPTION 'published after'; END IF;
  IF (SELECT count(*) FROM rename_batches) <> 33 OR (SELECT count(*) FROM rename_rows) <> 1398 OR (SELECT count(*) FROM source_capture_ledger) <> 211 THEN RAISE EXCEPTION 'rename, ledger after'; END IF;
  IF (SELECT count(*) FROM awards WHERE venue_id='ve_3246b2089c') <> 13 OR (SELECT count(*) FROM awards WHERE venue_id='ve_fbcb833f0c') <> 2 OR (SELECT count(*) FROM awards WHERE venue_id='ve_5ba6c32664') <> 1 OR EXISTS (SELECT 1 FROM price WHERE venue_id='ve_fbcb833f0c') THEN RAISE EXCEPTION 'masa, ginza after'; END IF;
  SELECT count(*) INTO x FROM venues v WHERE v.id IN ('ve_1b2f4308ae','ve_26a217eb82','ve_2935ce649e','ve_411ead11c6','ve_444325fab9','ve_5ba6c32664','ve_61cf53898d','ve_6c564637e8','ve_6ed52d9126','ve_7b02b65595','ve_a248207d2a','ve_e4697958f0','ve_e8097f89e5','ve_fbcb833f0c','ve_fe34271323','ve_3246b2089c','ve_6ea1945f41','ve_72a5d50fb1','ve_980121454e','ve_432649ae04','ve_1223ebdf9d','ve_310705d6ad','ve_993ab4e428','ve_6d0cf8a747','ve_bd0b5ff4e0','ve_08699c28d8') AND NOT EXISTS (SELECT 1 FROM awards a WHERE a.venue_id=v.id); IF x <> 0 THEN RAISE EXCEPTION 'venue with 0 awards %', x; END IF;
  SELECT string_agg(table_name||':'||action||'='||c, ',' ORDER BY table_name COLLATE "C", action COLLATE "C") INTO s FROM (SELECT table_name, action, count(*) c FROM audit_log WHERE id > aud_max GROUP BY 1,2) z;
  IF s IS DISTINCT FROM 'awards:INSERT=1,awards:UPDATE=33,cities:INSERT=1,cities:UPDATE=7,city_label_source:INSERT=22,listings:INSERT=11,price:UPDATE=1,redirects:INSERT=2,slugs:INSERT=11,slugs:UPDATE=2,venues:INSERT=11,venues:UPDATE=2' THEN RAISE EXCEPTION 'audit: %', s; END IF;
  RAISE NOTICE 'OK: all gates passed';
END
